// Mensaje de Evolution API (messages.upsert). Evolution 2.3 cambia remoteJid por remoteJidAlt (el teléfono real)
// cuando WhatsApp lo comparte; por si acaso se buscan también senderPn y remoteJidAlt. Si WhatsApp no comparte el
// teléfono, queda el identificador anónimo @lid, que también sirve para reconocer a quien escribe.
const cuerpo = $input.first().json.body || $input.first().json;
const datos = cuerpo.data || {};
const clave = datos.key || {};
const chatId = clave.remoteJid || '';
const deTelefono = [clave.remoteJid, clave.remoteJidAlt, clave.senderPn].find(j => typeof j === 'string' && j.endsWith('@s.whatsapp.net'));
const mensaje = datos.message || {};
const texto = (mensaje.conversation || (mensaje.extendedTextMessage && mensaje.extendedTextMessage.text) || '').trim().slice(0, 1000);
const procesar = cuerpo.event === 'messages.upsert' && cuerpo.instance === 'goltime' && clave.fromMe !== true
  && !chatId.endsWith('@g.us') && !chatId.endsWith('@broadcast') && !chatId.endsWith('@newsletter');

let respuestaFija = null;
if (!texto) {
  respuestaFija = 'Por ahora solo leo mensajes de texto 🙌 Escríbeme qué necesitas: precios, horarios, reservas o torneos.';
} else if (!deTelefono && !chatId.endsWith('@lid')) {
  respuestaFija = 'No logré reconocer tu WhatsApp 😕 Intenta de nuevo en un momento o reserva en la web de Goltime.';
}

return [{ json: {
  procesar,
  chatId,
  numero: deTelefono ? '+' + deTelefono.split('@')[0].split(':')[0] : null,
  lid: !deTelefono && chatId.endsWith('@lid') ? chatId.split('@')[0] : null,
  idMensaje: clave.id || null,
  enviadoEn: Number(datos.messageTimestamp) || Math.floor(Date.now() / 1000),
  texto,
  respuestaFija,
  recibidoEn: Date.now(),
} }];

// Deja el mensaje listo para el resto del flujo. Si vino agrupado, el texto es la suma de los mensajes seguidos y el
// tiempo de referencia es el del último (así la respuesta sale unos 10 s después de que la persona dejó de escribir).
// Los mensajes que no son de texto no se agrupan: pasan tal cual y reciben su respuesta fija.
const base = $('Leer mensaje').first().json;
const e = $input.first().json;
if (e.texto_junto === undefined) return [{ json: base }];
return [{ json: {
  ...base,
  texto: String(e.texto_junto).slice(0, 3000),
  idMensaje: e.ultimo_id || base.idMensaje,
  recibidoEn: Number(e.ultimo_ms) || base.recibidoEn,
  agrupados: Number(e.cantidad) || 1,
} }];

// Arma lo que recibe el agente: el contexto que da la API (fecha de Bogotá, quién escribe, sedes y políticas)
// más el mensaje. El prompt de sistema queda fijo, así OpenAI lo cachea y cuesta menos.
const c = $input.first().json;
const msg = $('Extraer mensaje').first().json;
if (c.botActivo === false) {
  return [{ json: { respuestaFija: 'En este momento el asistente de Goltime está en pausa ⏸️ Puedes reservar en la web o escribirle al administrador.' } }];
}
if (c.situacion === 'DESACTIVADO') {
  return [{ json: { respuestaFija: 'Tu cuenta de Goltime está desactivada. Comunícate con el administrador para revisarlo.' } }];
}
const sinVincular = c.puedeReservarSinCuenta
  ? (c.nombre ? `Si sigue sin vincular puede reservar sin cuenta; ya dio el nombre ${c.nombre}.`
     : `Si sigue sin vincular puede reservar sin cuenta dando su nombre${c.identificadoPor === 'LID' ? ' y un celular de contacto (WhatsApp no comparte su número)' : ''}.`)
  : 'Sin vincular no puede reservar: invítalo a vincular su cuenta o a registrarse en la web.';
const quien = {
  CLIENTE: `cliente con el WhatsApp vinculado (VINCULADO); se llama ${c.nombre}.`,
  SIN_VERIFICAR: `NO VINCULADO: hay una cuenta Goltime con este número, pero el WhatsApp no está vinculado. ${sinVincular}`,
  SIN_CUENTA: `NO VINCULADO: no sabemos si tiene cuenta en Goltime. ${sinVincular}`,
}[c.situacion] || 'desconocido.';
const p = c.politicas || {};
const sedes = (c.sedes || []).map(s => `[${s.id}] ${s.nombre} (${s.direccion}, ${s.ciudad})`).join('; ');
const entrada = `[Contexto] Hoy es ${c.dia} (${c.fecha}), son las ${c.hora} en Bogotá. Quien escribe: ${quien} `
  + `Sedes: ${sedes || 'ninguna'}. Políticas: cancelar o reprogramar hasta ${p.horasMinimasCancelacion} h antes; `
  + `máximo ${p.maxReprogramaciones} reprogramaciones; reservar con ${p.antelacionMinimaHoras} h de antelación y hasta ${p.antelacionMaximaDias} días; `
  + `las solicitudes las aprueba el administrador y expiran a las ${p.horasExpiracionAprobacion} h.`
  + (c.contacto ? ` Contacto del negocio: ${c.contacto}.` : '')
  + ` Enlace para vincular (perfil de Goltime): ${c.urlVincular}.`
  + `\n[Mensaje] ${msg.texto}`;
return [{ json: { respuestaFija: null, entrada } }];

// Una sola salida para todas las respuestas: la del agente, una fija (audio, pausa, cuenta desactivada) o la de error.
// La espera completa los 10 s desde que llegó el mensaje; Evolution muestra «escribiendo…» durante ese tiempo.
const j = $input.first().json;
const msg = $('Extraer mensaje').first().json;
const texto = (typeof j.output === 'string' && j.output.trim()) ? j.output.trim()
  : (j.respuestaFija || msg.respuestaFija
     || 'Uy, tuve un problema para responderte 😓 Intenta de nuevo en un momento o reserva en la web de Goltime.');
const transcurrido = Date.now() - msg.recibidoEn;
return [{ json: { texto, retraso: Math.max(1500, 10000 - transcurrido) } }];
